import { type LineSvgProps, ResponsiveLine as Line } from "@harbor-charts/line";
import {
	Component,
	Element,
	Host,
	Listen,
	Method,
	Prop,
	h,
} from "@stencil/core";
import * as React from "react";
import { createRoot } from "react-dom/client";
import retargetEvents from "react-shadow-dom-retarget-events";

import { line } from "@harbor/chart-config/line";

const {
	getLineBaseConfig,
	getLineCategoricalConfig,
	toggleLineClickingClass,
	toggleLinePointHoverClass,
} = line;

import merge from "deepmerge";
import {
	convertLineDataToCSV,
	generateOrSetTooltipContentRow,
	hideLinePopover,
	showHorizontalAxisPopover,
	showLinePointPopover,
	showVerticalAxisPopover,
	toggleLineLegendPopover,
	toggleLineMarkerLegendPopover,
	toggleLineSlicePopover,
} from "./chart-util";

import { browserDownloadCsv } from "../chart-board/board-util";
import { omitChartConfigKeys } from "../chart-board/chart-config-util";
import {
	type ChartPopoverOptions,
	applyChartPopoverOptions,
	isChartPopoverSelfManaged,
	resolveChartPopoverOptions,
} from "../chart-board/popover-options";
type HbrTooltipFunctions = {
	itemTooltip?: (...args: unknown[]) => string | object | false;
	legendTooltip?: (...args: unknown[]) => string | object | false;
	markerLegendTooltip?: (...args: unknown[]) => string | object | false;
};

type HbrLineChartConfig = Omit<Partial<LineSvgProps>, "tooltip"> &
	HbrTooltipFunctions & {
		areaStyle?: "solid" | "gradient";
		areaOpacity?: number;
	};

type ConfigWithNivoTooltip = HbrLineChartConfig & { tooltip?: unknown };

type LegendDatum = {
	id: string;
	color: string;
};

type MarkerLegendDatum = LegendDatum & {
	axis?: "x" | "y";
	markerLegendLabel?: string | number | Date;
	markerValue?: string | number | Date;
	markerAreaStyle?: "solid" | "shaded" | "gradient";
	markerLegendTooltip?: HbrTooltipFunctions["markerLegendTooltip"];
	markerLegendPopoverOptions?: ChartPopoverOptions;
	lineStyle?: {
		stroke?: string;
		strokeWidth?: number | string;
		strokeDasharray?: number | string;
	};
	opacity?: number;
};

type AxisTooltipFunction = (...args: unknown[]) => string | object | false;

type LineChartContextRoot = {
	config: HbrLineChartConfig;
	tooltipRef: HTMLHbrPopoverElement;
};

type LineData = Partial<LineSvgProps>["data"];
type AxisPopoverData = Parameters<typeof showHorizontalAxisPopover>[0];
type AxisPopoverEvent = Parameters<typeof showHorizontalAxisPopover>[1];
type TooltipContentData = Parameters<typeof generateOrSetTooltipContentRow>[0];
type TooltipContentFunction = Parameters<
	typeof generateOrSetTooltipContentRow
>[3];
type LinePoint = Parameters<typeof showLinePointPopover>[2];
type LinePointEvent = Parameters<typeof showLinePointPopover>[3];
type LegendConfigItem = Record<string, unknown> & {
	popoverOptions?: ChartPopoverOptions;
};
type LineAxisPopoverConfig = NonNullable<LineSvgProps["axisBottom"]> & {
	tooltip?: AxisTooltipFunction;
	popoverOptions?: ChartPopoverOptions;
	onMouseEnter?: (data: unknown, event: unknown, tick: unknown) => void;
	onMouseMove?: (data: unknown, event: unknown, tick: unknown) => void;
	onMouseLeave?: (data: unknown, event: unknown, tick: unknown) => void;
};
type ReactRoot = {
	render: (children: React.ReactElement) => void;
};

/**
 * @since 1.0.50
 * @status stable
 * @part chart - The chart element
 * @part header - The header element
 * @part popover-body - The popover body element, check hbr-popover for more details
 * @part popover-popup - The popover popup element,  check hbr-popover for more details
 * @part popover-arrow - The popover arrow element,  check hbr-popover for more details
 *
 * @slot header - Slot for header
 * @slot header-title - Slot for header title
 * @slot header-action - Slot for header action
 * @slot footer - Slot for footer
 * @slot loading-state - Slot for loading state
 * @slot empty-state - Slot for empty state
 * @slot content - Slot for popover content
 */
@Component({
	tag: "hbr-line-chart",
	styleUrl: "style.scss",
	shadow: true,
})
export class HbrLineChart {
	chartRef: HTMLElement;
	tooltipRef: HTMLHbrPopoverElement;
	boardRef: HTMLHbrChartBoardElement;

	/** Chart configuration object. Refer to https://nivo.rocks/line */
	@Prop({ mutable: true }) config: HbrLineChartConfig = { data: [] };
	/** Chart width */
	@Prop() width = "100%";
	/** Chart height */
	@Prop() height = "360px";
	/** Chart loading flag */
	@Prop() loading = false;

	/** New Magnetic UX chart type */
	@Prop({ reflect: true }) categorical = false;

	/** Final config before rendering, param1 is the final config, your customization should be done here */
	@Prop() modifyHbrConfig: (
		config: HbrLineChartConfig,
		createElement: typeof React.createElement,
		util: typeof line,
	) => ConfigWithNivoTooltip;

	/** Default popover props. Set `selfManaged` to let a categorical popover manage its own open and close behavior. */
	@Prop() popoverOptions: ChartPopoverOptions;

	@Element() private el: HTMLHbrLineChartElement;

	/** Public method for download data, use customFunc to create your own way to download data, such as pdf */
	@Method()
	async download(
		filename = "Export.csv",
		customFunc?: (data: LineData) => void,
	) {
		if (customFunc) {
			customFunc(this.config.data);
		} else {
			browserDownloadCsv(convertLineDataToCSV(this.config.data), filename);
		}
	}

	/** Public method to get popover reference, client can use this to control magnetic UX popover externally */
	@Method()
	async getPopoverRef() {
		return this.tooltipRef;
	}

	// saved react object after it is rendered
	// this is for update since react will complain if creating root again during update
	private contextRoot: ReactRoot | null = null;
	private activePopoverSelfManaged: boolean | null = null;

	private getLegendPopoverOptions() {
		return (this.config.legends?.[0] as LegendConfigItem | undefined)
			?.popoverOptions;
	}

	private getPopoverOptions(
		placement: ChartPopoverOptions["placement"] = "top",
		override?: ChartPopoverOptions,
	) {
		return resolveChartPopoverOptions(
			{ distance: 10, variant: "chart", placement },
			this.popoverOptions,
			this.categorical,
			override,
		);
	}

	private applyActivePopoverOptions(
		placement: ChartPopoverOptions["placement"] = "top",
		override?: ChartPopoverOptions,
	) {
		this.activePopoverSelfManaged = this.isPopoverSelfManaged(override);
		applyChartPopoverOptions(
			this.tooltipRef,
			this.getPopoverOptions(placement, override),
		);
	}

	private isPopoverSelfManaged(override?: ChartPopoverOptions) {
		return isChartPopoverSelfManaged(
			this.categorical,
			this.popoverOptions,
			override,
		);
	}
	private warnedAboutNivoTooltip = false;

	componentDidLoad() {
		this.renderChart();
		retargetEvents(this.el.shadowRoot);
	}

	componentShouldUpdate() {
		return this.renderChart();
	}

	@Listen("click", { passive: true })
	handleOutsideClick() {
		if (this.config.isInteractive ?? true) {
			toggleLinePointHoverClass(null, this.chartRef);
			toggleLineClickingClass(null, this.chartRef);
		}
	}

	@Listen("mouseout", { passive: true })
	handleHoverOut() {
		if (!(this.activePopoverSelfManaged ?? this.isPopoverSelfManaged())) {
			hideLinePopover(this.tooltipRef);
		}
	}

	legendShowPopover = (
		event: React.MouseEvent<Element> | React.FocusEvent<Element>,
		id: string,
		fill: string,
		chartContextRoot: LineChartContextRoot,
		popoverOptions?: ChartPopoverOptions,
	) => {
		const { config, tooltipRef } = chartContextRoot;
		this.applyActivePopoverOptions("top", popoverOptions);
		const legendDatum = { serieId: id, fill, event, data: config.data || [] };
		toggleLineLegendPopover(
			legendDatum,
			tooltipRef,
			(config as HbrTooltipFunctions).legendTooltip,
			this.chartRef,
		);
	};
	markerLegendShowPopover = (
		event: React.MouseEvent<Element> | React.FocusEvent<Element>,
		data: MarkerLegendDatum,
		chartContextRoot: LineChartContextRoot,
	) => {
		const { config, tooltipRef } = chartContextRoot;
		this.applyActivePopoverOptions("top", data.markerLegendPopoverOptions);
		const markerTooltip =
			data.markerLegendTooltip ?? (config as HbrTooltipFunctions).legendTooltip;
		toggleLineMarkerLegendPopover(data, tooltipRef, markerTooltip, event);
	};
	legendHidePopover = (chartContextRoot: LineChartContextRoot) => {
		toggleLineLegendPopover(null, chartContextRoot.tooltipRef);
		toggleLineMarkerLegendPopover(null, chartContextRoot.tooltipRef);
	};

	renderChart = () => {
		const configWithNivoTooltip = this.config as ConfigWithNivoTooltip;
		if (
			!this.warnedAboutNivoTooltip &&
			configWithNivoTooltip.tooltip !== undefined
		) {
			console.warn(
				"hbr-line-chart: config.tooltip is not supported. Use itemTooltip, legendTooltip, or markerLegendTooltip instead.",
			);
			this.warnedAboutNivoTooltip = true;
		}
		const publicConfig = omitChartConfigKeys(configWithNivoTooltip, [
			"tooltip",
		]) as HbrLineChartConfig;
		const getConfig = this.categorical
			? getLineCategoricalConfig
			: getLineBaseConfig;
		const axisBottomConfig = this.config.axisBottom as
			| LineAxisPopoverConfig
			| undefined;
		const axisLeftConfig = this.config.axisLeft as
			| LineAxisPopoverConfig
			| undefined;
		const axisTopConfig = this.config.axisTop as
			| LineAxisPopoverConfig
			| undefined;
		const axisRightConfig = this.config.axisRight as
			| LineAxisPopoverConfig
			| undefined;
		const legendPopoverOptions = this.getLegendPopoverOptions();
		const getAxisWithTooltip = (
			axisConfig: LineAxisPopoverConfig | undefined,
			placement: ChartPopoverOptions["placement"],
			dimension: "horizontal" | "vertical",
		) => ({
			...axisConfig,
			onMouseEnter: (data: unknown, event: unknown, tick: unknown) => {
				const lineConfig = this.config as Partial<LineSvgProps> & {
					isSparkline?: boolean;
				};
				if (lineConfig.isSparkline && lineConfig.isInteractive === false) {
					hideLinePopover(this.tooltipRef);
					return;
				}

				if (this.categorical) {
					this.applyActivePopoverOptions(placement, axisConfig?.popoverOptions);
				}
				const showAxisPopover =
					dimension === "horizontal"
						? showHorizontalAxisPopover
						: showVerticalAxisPopover;
				showAxisPopover(
					data as AxisPopoverData,
					event as AxisPopoverEvent,
					this,
					axisConfig?.tooltip,
				);
				axisConfig?.onMouseEnter?.(data, event, tick);
			},
			onMouseMove: (data: unknown, event: unknown, tick: unknown) => {
				if (this.categorical) {
					this.applyActivePopoverOptions(placement, axisConfig?.popoverOptions);
				}
				const showAxisPopover =
					dimension === "horizontal"
						? showHorizontalAxisPopover
						: showVerticalAxisPopover;
				showAxisPopover(
					data as AxisPopoverData,
					event as AxisPopoverEvent,
					this,
					axisConfig?.tooltip,
				);
				axisConfig?.onMouseMove?.(data, event, tick);
			},
			onMouseLeave: (data: unknown, event: unknown, tick: unknown) => {
				if (!this.isPopoverSelfManaged(axisConfig?.popoverOptions)) {
					hideLinePopover(this.tooltipRef);
				}
				axisConfig?.onMouseLeave?.(data, event, tick);
			},
		});

		const baseConfig = getConfig(
			{
				...publicConfig,
				axisBottom: getAxisWithTooltip(
					axisBottomConfig,
					"bottom",
					"horizontal",
				),
				axisLeft: getAxisWithTooltip(axisLeftConfig, "left", "vertical"),
				...(this.categorical && axisTopConfig
					? {
							axisTop: getAxisWithTooltip(axisTopConfig, "top", "horizontal"),
					  }
					: {}),
				...(this.categorical && axisRightConfig
					? {
							axisRight: getAxisWithTooltip(
								axisRightConfig,
								"right",
								"vertical",
							),
					  }
					: {}),
			},
			{
				itemsEventHandlers: {
					tooltipFunc: (
						data: unknown,
						itemTooltip: unknown,
						event?: unknown,
					) => {
						const tooltipItemFunc = itemTooltip as TooltipContentFunction;
						if (!event) {
							return generateOrSetTooltipContentRow(
								data as TooltipContentData,
								this,
								true,
								tooltipItemFunc,
							);
						}

						this.applyActivePopoverOptions();

						if (
							!data ||
							typeof data !== "object" ||
							!("slice" in (data as TooltipContentData))
						) {
							if (
								!(this.activePopoverSelfManaged ?? this.isPopoverSelfManaged())
							) {
								hideLinePopover(this.tooltipRef);
							}
							return null;
						}

						const slice = (data as TooltipContentData).slice;
						if (!slice?.points?.length) {
							if (
								!(this.activePopoverSelfManaged ?? this.isPopoverSelfManaged())
							) {
								hideLinePopover(this.tooltipRef);
							}
							return null;
						}

						toggleLineSlicePopover(
							this.tooltipRef,
							this.chartRef,
							slice as { points?: LinePoint[] },
							event as LinePointEvent,
							tooltipItemFunc,
						);
						return null;
					},
					sliceTooltipFunc: (
						data: unknown,
						itemTooltip: unknown,
						showOnlySelectedSerie: boolean,
					) =>
						generateOrSetTooltipContentRow(
							data as TooltipContentData,
							this,
							showOnlySelectedSerie,
							itemTooltip as TooltipContentFunction,
						),
					onFocus: (data: unknown, event: unknown) => {
						this.applyActivePopoverOptions();
						showLinePointPopover(
							this.tooltipRef,
							this.chartRef,
							data as LinePoint,
							event as LinePointEvent,
							(this.config as LineSvgProps & HbrTooltipFunctions).itemTooltip,
						);
					},
				},
				legendsEventHandlers: {
					onMouseEnter: (
						data: LegendDatum | MarkerLegendDatum,
						event: React.MouseEvent<Element>,
					) =>
						"markerValue" in data
							? this.markerLegendShowPopover(event, data, this)
							: this.legendShowPopover(
									event,
									data.id,
									data.color,
									this,
									legendPopoverOptions,
							  ),
					onMouseMove: (
						data: LegendDatum | MarkerLegendDatum,
						event: React.MouseEvent<Element>,
					) =>
						"markerValue" in data
							? this.markerLegendShowPopover(event, data, this)
							: this.legendShowPopover(
									event,
									data.id,
									data.color,
									this,
									legendPopoverOptions,
							  ),
					onMouseLeave: (data: LegendDatum | MarkerLegendDatum) => {
						const popoverOptions =
							"markerValue" in data
								? data.markerLegendPopoverOptions
								: legendPopoverOptions;
						if (!this.isPopoverSelfManaged(popoverOptions)) {
							this.legendHidePopover(this);
						}
					},
					onFocus: (
						data: LegendDatum | MarkerLegendDatum,
						event: React.FocusEvent<Element>,
					) =>
						"markerValue" in data
							? this.markerLegendShowPopover(event, data, this)
							: this.legendShowPopover(
									event,
									data.id,
									data.color,
									this,
									legendPopoverOptions,
							  ),
					onBlur: (_data, _event) => {
						this.activePopoverSelfManaged = null;
						this.legendHidePopover(this);
					},
					onClick: (
						data: LegendDatum | MarkerLegendDatum,
						event: React.MouseEvent<Element>,
					) =>
						"markerValue" in data
							? this.markerLegendShowPopover(event, data, this)
							: this.legendShowPopover(
									event,
									data.id,
									data.color,
									this,
									legendPopoverOptions,
							  ),
				},
			},
		);

		const existingEventHandlers = {
			onMouseEnter: baseConfig.onMouseEnter,
			onMouseLeave: baseConfig.onMouseLeave,
			onClick: baseConfig.onClick,
			onblur: baseConfig.onBlur,
			onFocus: baseConfig.onFocus,
		};

		let fullConfig = merge(baseConfig, publicConfig, {
			customMerge: (key) => {
				if (key === "legends") {
					return (a: LegendConfigItem[], b: LegendConfigItem[]) => {
						const ret =
							a.length > b.length
								? a.map((r: LegendConfigItem, i: number) => ({ ...r, ...b[i] }))
								: b.map((r: LegendConfigItem, i: number) => ({
										...r,
										...a[i],
								  }));
						return ret;
					};
				}
				if (key === "tickValues") {
					return (_a: unknown, b: unknown) => b;
				}
				if (key === "colors") {
					return (_a: unknown, b: unknown) => b;
				}
			},
		}) as unknown as ConfigWithNivoTooltip;

		fullConfig = {
			...fullConfig,
			...existingEventHandlers,
		} as unknown as ConfigWithNivoTooltip;

		if (this.modifyHbrConfig) {
			fullConfig = this.modifyHbrConfig(
				fullConfig as HbrLineChartConfig,
				React.createElement,
				line,
			);
		}
		if (!this.contextRoot) {
			this.contextRoot = createRoot(this.chartRef) as unknown as ReactRoot;
			this.contextRoot.render(
				React.createElement(
					Line as unknown as React.ElementType,
					fullConfig as LineSvgProps,
					null,
				),
			);
		}
		this.contextRoot.render(
			React.createElement(
				Line as unknown as React.ElementType,
				fullConfig as LineSvgProps,
				null,
			),
		);

		if (this.boardRef.setChartConfig) {
			this.boardRef.setChartConfig(fullConfig);
		}
	};

	render() {
		this.el.style.width = this.width;
		this.el.style.height = this.height;
		const popoverOptions = resolveChartPopoverOptions(
			{ distance: 10, variant: "chart" },
			this.popoverOptions,
			this.categorical,
		);

		// Chart-managed visibility remains the default due to the chart mesh.
		return (
			<Host>
				{!this.config.data?.length && this.categorical && (
					<div slot="header" part="header" class="chart-line__header">
						<slot name="header">
							<div>
								<slot name="header-title" />
							</div>
							<div>
								<slot name="header-action" />
							</div>
						</slot>
					</div>
				)}
				<hbr-chart-board
					type={this.categorical ? "categorical" : "line"}
					ref={(el) => {
						this.boardRef = el;
					}}
					isLoading={this.loading}
					isEmpty={!this.config.data?.length}
					style={{ width: this.width, height: this.height }}
					exportparts="empty-state-illustration, empty-state-image, loading-state-illustration, loading-state-image"
				>
					<hbr-popover
						{...(popoverOptions as object)}
						ref={(el) => {
							this.tooltipRef = el;
						}}
						part="popover"
						exportparts="base__popup:popover-popup, base__arrow:popover-arrow, body:popover-body"
						anchor=""
					>
						<div slot="content" />
					</hbr-popover>
					{(this.config.data?.length || !this.categorical) && (
						<div slot="header" part="header" class="chart-line__header">
							<slot name="header">
								<div>
									<slot name="header-title" />
								</div>
								<div>
									<slot name="header-action" />
								</div>
							</slot>
						</div>
					)}
					<div
						ref={(el) => {
							this.chartRef = el;
						}}
						class={`--hbr-chart --line-chart ${
							this.categorical ? "--categorical" : ""
						}`}
						part="chart"
					/>
					<slot name="footer" />
					<slot slot="loading-state" name="loading-state" />
					<slot slot="empty-state" name="empty-state" />
				</hbr-chart-board>
			</Host>
		);
	}
}
