import * as React from "react";

import { line } from "@harbor/chart-config/line";
import { h } from "@stencil/core";
import { createDOMElementFromVNode } from "../../utils/function-helper";
import { sanitizeHtml } from "../../utils/sanitizeHtml";
import { hideChartPopover, showChartPopover } from "../chart-board/board-util";
const { getLineSymbols, getCategoricalColors } = line;

type LineChartPoint = {
	id?: string;
	index?: number;
	x: string | number;
	y: string | number;
	color?: string;
	serieId: string;
	data: {
		x?: string | number | Date;
		xFormatted?: string;
		y?: string | number | null;
		yFormatted?: string;
		[key: string]: unknown;
	};
	symbol?: {
		svg: (color: string) => string;
	};
};

type LineSeries = {
	id: string | number;
	data: Array<{
		x?: string | number | Date;
		y?: string | number | Date | null;
	}>;
};

type MarkerLegendPopoverData = {
	axis?: "x" | "y";
	markerLegendLabel?: string | number | Date;
	markerValue?: string | number | Date;
	markerAreaStyle?: "solid" | "shaded" | "gradient";
	color?: string;
	opacity?: number;
	lineStyle?: {
		stroke?: string;
		strokeWidth?: number | string;
		strokeDasharray?: number | string;
	};
};

type LineTooltipFunction = (...args: unknown[]) => string | object | false;

type LineChartContextRoot = {
	tooltipRef: HTMLHbrPopoverElement;
	chartRef: HTMLElement;
};

type PopoverTriggerEvent =
	| MouseEvent
	| React.MouseEvent<Element>
	| React.FocusEvent<Element>;

const toSvgId = (value: string) => value.replace(/[^a-zA-Z0-9_-]/g, "-");

function hasRenderableLineValue(point: LineChartPoint) {
	return point.y != null;
}

// axis tooltip content does not have point color
// so we need to manually inject colors to data
function getSymbolByType(type?: string | null) {
	return getLineSymbols().find(
		(symbol: { type: string }) => symbol.type === type,
	);
}

function injectCategoricalColorsAndSymbolToData(
	data: LineChartPoint[],
	chartRef: HTMLElement,
) {
	const visibleData = data.filter(hasRenderableLineValue);
	const symbols = getLineSymbols();
	const colors = getCategoricalColors(visibleData.length);

	const series = visibleData.reduce((total: string[], cur: LineChartPoint) => {
		if (total.indexOf(cur.serieId) === -1) {
			total.push(cur.serieId);
		}
		return total;
	}, []);

	return visibleData.map((d: LineChartPoint, i: number) => ({
		...d,
		symbol:
			getSymbolByType(
				Array.from(chartRef.querySelectorAll("[series]"))
					.find((element) => element.getAttribute("series") === d.serieId)
					?.getAttribute("type"),
			) || symbols[series.indexOf(d.serieId) % symbols.length],
		color: d.color || colors[i],
	}));
}

function showLinePointPopover(
	tooltipRef: HTMLHbrPopoverElement,
	chartRef: HTMLElement,
	point: LineChartPoint,
	event: MouseEvent | Record<string, unknown>,
	customTooltipFunc?: LineTooltipFunction,
) {
	const selector = `[xid='${point.x}'][yid='${point.y}']`;

	const type = chartRef.querySelector(selector)?.getAttribute("type");

	const targetSymbol = getSymbolByType(type);
	showChartPopover(
		tooltipRef,
		point,
		{
			...event,
			target: type
				? selector
				: chartRef.querySelectorAll("circle")[point.index || 0],
		} as MouseEvent,
		() => customTooltipFunc?.(point, event, h),
		() => {
			const content = `<div class="--hbr-line-popover-row">
				<div>
					${targetSymbol?.svg(point.color || "") || ""}
					${point.data.xFormatted}
				</div>
				<div>
					${point.data.yFormatted}
				</div>
			</div>`;
			return content;
		},
	);
}

function toggleLineSlicePopover(
	tooltipRef: HTMLHbrPopoverElement,
	chartRef: HTMLElement,
	slice: { points?: LineChartPoint[] },
	event: MouseEvent | Record<string, unknown>,
	customTooltipFunc?: LineTooltipFunction,
) {
	const points = slice.points || [];
	if (!points.length) {
		hideChartPopover(tooltipRef);
		return;
	}

	const eventTarget =
		event && typeof event === "object" && "currentTarget" in event
			? (event as MouseEvent & { currentTarget?: EventTarget | null })
					.currentTarget
			: (event as MouseEvent & { target?: EventTarget | null }).target;

	const symbols = getLineSymbols();
	const defaultContent = points
		.map((point: LineChartPoint, index: number) => {
			const selector = `[xid='${point.x}'][yid='${point.y}']`;
			const type = chartRef.querySelector(selector)?.getAttribute("type");
			const targetSymbol = symbols.find(
				(r: { type: string }) => r.type === type,
			);
			const pointKey = `${point.serieId}-${String(point.data.x)}-${String(
				point.id,
			)}-${index}`;

			return `
				<div key="${pointKey}" class="--hbr-line-popover-row">
					<div>
						<span>${targetSymbol?.svg(point.color || "") || ""}</span>
						${point.serieId}
					</div>
					<div>${point.data.yFormatted || point.data.y || ""}</div>
				</div>
			`;
		})
		.join("");

	showChartPopover(
		tooltipRef,
		points,
		{
			...event,
			target:
				(eventTarget as HTMLElement | SVGElement | null) ||
				chartRef.querySelector(
					`[xid='${points[0].x}'][yid='${points[0].y}']`,
				) ||
				chartRef.querySelectorAll("circle")[points[0].index || 0],
		} as MouseEvent,
		customTooltipFunc ? () => customTooltipFunc(points, event, h) : undefined,
		() => defaultContent,
	);
}

function toggleLineLegendPopover(
	legendData: {
		serieId: string;
		data: LineSeries[];
		event: PopoverTriggerEvent;
		fill: string;
	} | null,
	tooltipRef: HTMLHbrPopoverElement,
	customTooltipFunc?: LineTooltipFunction,
	chartRef?: HTMLElement,
) {
	const { serieId, data, event, fill } = legendData || {};

	if (!legendData) {
		hideChartPopover(tooltipRef);
	} else {
		const symbols = getLineSymbols();

		// hard wire id may have some issue
		const series = data.reduce(
			(total: Array<string | number>, cur: LineSeries) => {
				if (total.indexOf(cur.id) === -1) {
					total.push(cur.id);
				}
				return total;
			},
			[],
		);

		const targetSymbol =
			(chartRef &&
				getSymbolByType(
					Array.from(chartRef.querySelectorAll("[series]"))
						.find((element) => element.getAttribute("series") === serieId)
						?.getAttribute("type"),
				)) ||
			symbols[series.indexOf(serieId) % symbols.length];
		const targetSeies =
			data.find((r: LineSeries) => r.id === serieId)?.data || [];

		showChartPopover(
			tooltipRef,
			{ data, event },
			event as unknown as MouseEvent,
			() =>
				customTooltipFunc?.(
					{ ...data, targetSymbol, targetSeies, serieId },
					event,
					h,
				),
			() => {
				let res = "";
				targetSeies.forEach(
					(r: { x?: string | number; y?: string | number | null }) => {
						res += `<div class="--hbr-line-popover-row">
					<div>
						${targetSymbol?.svg(fill) || ""}
						${r.x}
					</div>
					<div>
						${r.y}
					</div>
				</div>`;
					},
				);
				return res;
			},
		);
	}
}

function toggleLineMarkerLegendPopover(
	legendData: MarkerLegendPopoverData | null,
	tooltipRef: HTMLHbrPopoverElement,
	customTooltipFunc?: LineTooltipFunction,
	event?: PopoverTriggerEvent,
) {
	if (!legendData || typeof customTooltipFunc !== "function") {
		hideChartPopover(tooltipRef);
		return;
	}

	const markerLabel =
		legendData.markerLegendLabel ?? legendData.markerValue ?? "";
	const markerValue =
		legendData.markerValue ?? legendData.markerLegendLabel ?? "";
	const fill = legendData.color || "rgba(255, 0, 0, 0.1)";
	const stroke = legendData.lineStyle?.stroke || fill;
	const strokeWidth = Math.min(
		Number(legendData.lineStyle?.strokeWidth) || 3,
		3,
	);
	const dashArray = legendData.lineStyle?.strokeDasharray;
	const markerKey = `${legendData.axis ?? "y"}-${markerLabel}-${markerValue}`;
	const gradientId = `marker-area-gradient-${toSvgId(String(markerKey))}`;
	const isHorizontalArea = legendData.axis === "x";
	const gradientX2 = isHorizontalArea ? "100%" : "0%";
	const gradientY2 = isHorizontalArea ? "0%" : "100%";
	const gradientStartOpacity = isHorizontalArea ? 0 : legendData.opacity ?? 1;
	const gradientEndOpacity = isHorizontalArea ? legendData.opacity ?? 1 : 0;
	const shadedPattern =
		legendData.markerAreaStyle === "shaded"
			? `
		<defs>
			<pattern id="marker-area-shaded-pattern" patternUnits="userSpaceOnUse" width="4" height="4" patternTransform="rotate(45)">
				<rect x="0" y="0" width="4" height="4" fill="rgba(255, 255, 255, 0.3)"></rect>
				<path d="M0 0 L0 4" stroke="rgba(255, 255, 255, 0.7)" stroke-width="2"></path>
			</pattern>
		</defs>
		`
			: "";
	const gradientDefs =
		legendData.markerAreaStyle === "gradient"
			? `
		<defs>
			<linearGradient id="${gradientId}" x1="0%" y1="0%" x2="${gradientX2}" y2="${gradientY2}">
				<stop offset="0%" stop-color="${fill}" stop-opacity="${gradientStartOpacity}"></stop>
				<stop offset="100%" stop-color="${fill}" stop-opacity="${gradientEndOpacity}"></stop>
			</linearGradient>
		</defs>
		`
			: "";
	const symbol = `<svg width="20" height="16" viewBox="0 0 20 16" aria-hidden="true" focusable="false">${shadedPattern}
		${gradientDefs}
		<rect x="0" y="2" width="20" height="12" fill="${
			legendData.markerAreaStyle === "gradient" ? `url(#${gradientId})` : fill
		}" opacity="${
			legendData.markerAreaStyle === "gradient" ? 1 : legendData.opacity ?? 1
		}"></rect>
		${
			legendData.markerAreaStyle === "shaded"
				? '<rect x="0" y="2" width="20" height="12" fill="url(#marker-area-shaded-pattern)"></rect>'
				: ""
		}
		<line x1="0" y1="2" x2="20" y2="2" stroke="${stroke}" stroke-width="${strokeWidth}"${
			dashArray ? ` stroke-dasharray="${dashArray}"` : ""
		}></line>
	</svg>`;

	showChartPopover(
		tooltipRef,
		legendData,
		event as unknown as MouseEvent,
		() =>
			customTooltipFunc?.(
				{
					...legendData,
					markerLabel,
					markerValue,
				},
				event,
				h,
			),
		() =>
			`<div class="--hbr-line-popover-row">
				<div>
					${symbol}
					${markerLabel}
				</div>
				<div>
					${markerValue}
				</div>
			</div>`,
	);
}

/**
 *
 * @param data - either slice data or point data
 * @param chartContextRoot
 * @returns either return a tooltip div for nivo slice to consume
 * @returns or set the content of a existing hbr-popover with no return
 */
function generateOrSetTooltipContentRow(
	data: {
		slice?: { points?: LineChartPoint[] };
		point?: LineChartPoint;
	} | null,
	chartContextRoot: LineChartContextRoot,
	_showOnlySelectedSerie = false,
	itemTooltip?: LineTooltipFunction,
) {
	const { slice, point } = data || {};
	const { tooltipRef, chartRef } = chartContextRoot;
	const symbols = getLineSymbols();
	if (slice?.points) {
		if (itemTooltip && typeof itemTooltip === "function") {
			const custom = itemTooltip(slice.points, null, h);

			const ret = React.createElement("div", {
				ref: (el: HTMLDivElement | null) => {
					if (el) {
						el.replaceChildren();

						if (typeof custom === "string") {
							void sanitizeHtml(custom).then((sanitizedContent) => {
								el.innerHTML = sanitizedContent;
							});
							return;
						}

						const customNode = createDOMElementFromVNode(custom);
						if (customNode) {
							el.appendChild(customNode);
						}
					}
				},
			});
			return React.createElement(
				"div",
				{
					className: "--hbr-line-popover-container",
				},
				ret,
			);
		}
		const pointElem = slice.points.map(
			(point: LineChartPoint, index: number) => {
				const selector = `[xid='${point.x}'][yid='${point.y}']`;
				const type = chartRef.querySelector(selector)?.getAttribute("type");
				const pointKey = `${point.serieId}-${String(point.data.x)}-${String(
					point.id,
				)}-${index}`;

				const targetSymbol = symbols.find(
					(r: { type: string }) => r.type === type,
				);

				return React.createElement(
					"div",
					{
						key: pointKey,
						className: "--hbr-line-popover-row",
					},
					React.createElement(
						"div",
						{},
						React.createElement("span", {
							ref: (el: HTMLSpanElement | null) => {
								if (el) {
									el.innerHTML = targetSymbol?.svg(point.color) || "";
								}
							},
						}),
						` ${point.serieId}`,
					),
					React.createElement("div", {}, point.data.yFormatted),
				);
			},
		);

		return React.createElement(
			"div",
			{
				className: "--hbr-line-popover-container",
			},
			pointElem,
		);
	}
	if (point) {
		showLinePointPopover(tooltipRef, chartRef, point, {}, itemTooltip);
	} else {
		hideChartPopover(tooltipRef);
	}
}

const showHorizontalAxisPopover = (
	data: LineChartPoint[],
	event: MouseEvent & { target: EventTarget | null },
	chartContextRoot: LineChartContextRoot,
	customTooltipFunc?: LineTooltipFunction,
) => {
	const { tooltipRef, chartRef } = chartContextRoot;
	const { target } = event;
	const fullData = injectCategoricalColorsAndSymbolToData(data, chartRef);

	showChartPopover(
		tooltipRef,
		fullData,
		event,
		() => customTooltipFunc?.(fullData, target),
		() =>
			fullData
				.map(
					(d: LineChartPoint) =>
						`<div class="--hbr-line-popover-row">
  				<div>
  					${d.symbol?.svg(d.color) || ""}
  					${d.serieId}
  				</div>
  				<div>
  					${d.y}
  				</div>
  			</div>`,
				)
				.join(""),
	);
};

const showVerticalAxisPopover = (
	data: LineChartPoint[],
	event: MouseEvent & { target: EventTarget | null },
	chartContextRoot: LineChartContextRoot,
	customTooltipFunc?: LineTooltipFunction,
) => {
	const { tooltipRef, chartRef } = chartContextRoot;
	const { target } = event;
	const fullData = injectCategoricalColorsAndSymbolToData(data, chartRef);

	showChartPopover(
		tooltipRef,
		fullData,
		event,
		() => customTooltipFunc?.(fullData, target),
		() => false,
	);
};

const hideLinePopover = (tooltipRef: HTMLHbrPopoverElement) => {
	hideChartPopover(tooltipRef);
};

const convertLineDataToCSV = (arr: LineSeries[]) => {
	let csv = "group,x,y\n";
	arr.forEach((group: LineSeries) => {
		const groupId = group.id;
		group.data.forEach(
			(item: { x?: string | number; y?: string | number | null }) => {
				const x = item.x || "";
				const y = item.y || "";
				csv += `${groupId},${x},${y}\n`;
			},
		);
	});

	return csv;
};

export {
	generateOrSetTooltipContentRow,
	showHorizontalAxisPopover,
	showVerticalAxisPopover,
	showLinePointPopover,
	toggleLineSlicePopover,
	toggleLineLegendPopover,
	toggleLineMarkerLegendPopover,
	hideLinePopover,
	convertLineDataToCSV,
};
